1	const { Request, Response, NextFunction } = require('express')
2	const Logger = require('../Logger')
3	const SocketAuthority = require('../SocketAuthority')
4	const Database = require('../Database')
5	const htmlSanitizer = require('../utils/htmlSanitizer')
6	
7	/**
8	 * @typedef RequestUserObject
9	 * @property {import('../models/User')} user
10	 *
11	 * @typedef {Request & RequestUserObject} RequestWithUser
12	 *
13	 * @typedef RequestEntityObject
14	 * @property {import('../models/Playlist')} playlist
15	 *
16	 * @typedef {RequestWithUser & RequestEntityObject} PlaylistControllerRequest
17	 */
18	
19	class PlaylistController {
20	  constructor() {}
21	
22	  /**
23	   * POST: /api/playlists
24	   * Create playlist
25	   *
26	   * @param {RequestWithUser} req
27	   * @param {Response} res
28	   */
29	  async create(req, res) {
30	    const reqBody = req.body || {}
31	
32	    // Validation
33	    const nameCleaned = htmlSanitizer.stripAllTags(reqBody.name)
34	    if (!nameCleaned || !reqBody.libraryId) {
35	      return res.status(400).send('Invalid playlist data')
36	    }
37	    if (reqBody.description && typeof reqBody.description !== 'string') {
38	      return res.status(400).send('Invalid playlist description')
39	    }
40	    if (!req.user.checkCanAccessLibrary(reqBody.libraryId)) {
41	      Logger.warn(`[PlaylistController] User "${req.user.username}" attempted to create playlist in inaccessible library ${reqBody.libraryId}`)
42	      return res.sendStatus(403)
43	    }
44	    const items = reqBody.items || []
45	    const isPodcast = items.some((i) => i.episodeId)
46	    const libraryItemIds = new Set()
47	    for (const item of items) {
48	      if (!item.libraryItemId || typeof item.libraryItemId !== 'string') {
49	        return res.status(400).send('Invalid playlist item')
50	      }
51	      if (isPodcast && (!item.episodeId || typeof item.episodeId !== 'string')) {
52	        return res.status(400).send('Invalid playlist item episodeId')
53	      } else if (!isPodcast && item.episodeId) {
54	        return res.status(400).send('Invalid playlist item episodeId')
55	      }
56	      libraryItemIds.add(item.libraryItemId)
57	    }
58	
59	    // Load library items
60	    const libraryItems = await Database.libraryItemModel.findAll({
61	      attributes: ['id', 'mediaId', 'mediaType', 'libraryId'],
62	      where: {
63	        id: Array.from(libraryItemIds),
64	        libraryId: reqBody.libraryId,
65	        mediaType: isPodcast ? 'podcast' : 'book'
66	      }
67	    })
68	    if (libraryItems.length !== libraryItemIds.size) {
69	      return res.status(400).send('Invalid playlist data. Invalid items')
70	    }
71	
72	    // Validate podcast episodes
73	    if (isPodcast) {
74	      const podcastEpisodeIds = items.map((i) => i.episodeId)
75	      const podcastEpisodes = await Database.podcastEpisodeModel.findAll({
76	        attributes: ['id'],
77	        where: {
78	          id: podcastEpisodeIds
79	        }
80	      })
81	      if (podcastEpisodes.length !== podcastEpisodeIds.length) {
82	        return res.status(400).send('Invalid playlist data. Invalid podcast episodes')
83	      }
84	    }
85	
86	    const transaction = await Database.sequelize.transaction()
87	    try {
88	      // Create playlist
89	      const newPlaylist = await Database.playlistModel.create(
90	        {
91	          libraryId: reqBody.libraryId,
92	          userId: req.user.id,
93	          name: nameCleaned,
94	          description: reqBody.description || null
95	        },
96	        { transaction }
97	      )
98	
99	      // Create playlistMediaItems
100	      const playlistItemPayloads = []
101	      for (const [index, item] of items.entries()) {
102	        const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
103	        playlistItemPayloads.push({
104	          playlistId: newPlaylist.id,
105	          mediaItemId: item.episodeId || libraryItem.mediaId,
106	          mediaItemType: item.episodeId ? 'podcastEpisode' : 'book',
107	          order: index + 1
108	        })
109	      }
110	
111	      await Database.playlistMediaItemModel.bulkCreate(playlistItemPayloads, { transaction })
112	
113	      await transaction.commit()
114	
115	      newPlaylist.playlistMediaItems = await newPlaylist.getMediaItemsExpandedWithLibraryItem()
116	
117	      const jsonExpanded = newPlaylist.toOldJSONExpanded()
118	      SocketAuthority.clientEmitter(newPlaylist.userId, 'playlist_added', jsonExpanded)
119	      res.json(jsonExpanded)
120	    } catch (error) {
121	      await transaction.rollback()
122	      Logger.error('[PlaylistController] create:', error)
123	      res.status(500).send('Failed to create playlist')
124	    }
125	  }
126	
127	  /**
128	   * @deprecated - Use /api/libraries/:libraryId/playlists
129	   * This is not used by Abs web client or mobile apps
130	   * TODO: Remove this endpoint or make it the primary
131	   *
132	   * GET: /api/playlists
133	   * Get all playlists for user
134	   *
135	   * @param {RequestWithUser} req
136	   * @param {Response} res
137	   */
138	  async findAllForUser(req, res) {
139	    const playlistsForUser = await Database.playlistModel.getOldPlaylistsForUserAndLibrary(req.user.id)
140	    const accessiblePlaylists = playlistsForUser.filter((p) => req.user.checkCanAccessLibrary(p.libraryId))
141	    res.json({
142	      playlists: accessiblePlaylists
143	    })
144	  }
145	
146	  /**
147	   * GET: /api/playlists/:id
148	   *
149	   * @param {PlaylistControllerRequest} req
150	   * @param {Response} res
151	   */
152	  async findOne(req, res) {
153	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
154	    res.json(req.playlist.toOldJSONExpanded())
155	  }
156	
157	  /**
158	   * PATCH: /api/playlists/:id
159	   * Update playlist
160	   *
161	   * Used for updating name and description or reordering items
162	   *
163	   * @param {PlaylistControllerRequest} req
164	   * @param {Response} res
165	   */
166	  async update(req, res) {
167	    // Validation
168	    const reqBody = req.body || {}
169	    if (reqBody.libraryId || reqBody.userId) {
170	      // Could allow support for this if needed with additional validation
171	      return res.status(400).send('Invalid playlist data. Cannot update libraryId or userId')
172	    }
173	    if (reqBody.name && typeof reqBody.name !== 'string') {
174	      return res.status(400).send('Invalid playlist name')
175	    }
176	    if (reqBody.description && typeof reqBody.description !== 'string') {
177	      return res.status(400).send('Invalid playlist description')
178	    }
179	    if (reqBody.items && (!Array.isArray(reqBody.items) || reqBody.items.some((i) => !i.libraryItemId || typeof i.libraryItemId !== 'string' || (i.episodeId && typeof i.episodeId !== 'string')))) {
180	      return res.status(400).send('Invalid playlist items')
181	    }
182	
183	    const playlistUpdatePayload = {}
184	
185	    const nameCleaned = htmlSanitizer.stripAllTags(reqBody.name)
186	    if (nameCleaned) {
187	      playlistUpdatePayload.name = nameCleaned
188	    }
189	    if (reqBody.description) playlistUpdatePayload.description = reqBody.description
190	
191	    // Update name and description
192	    let wasUpdated = false
193	    if (Object.keys(playlistUpdatePayload).length) {
194	      req.playlist.set(playlistUpdatePayload)
195	      const changed = req.playlist.changed()
196	      if (changed?.length) {
197	        await req.playlist.save()
198	        Logger.debug(`[PlaylistController] Updated playlist ${req.playlist.id} keys [${changed.join(',')}]`)
199	        wasUpdated = true
200	      }
201	    }
202	
203	    // If array of items is set then update order of playlist media items
204	    if (reqBody.items?.length) {
205	      const libraryItemIds = Array.from(new Set(reqBody.items.map((i) => i.libraryItemId)))
206	      const libraryItems = await Database.libraryItemModel.findAll({
207	        attributes: ['id', 'mediaId', 'mediaType'],
208	        where: {
209	          id: libraryItemIds
210	        }
211	      })
212	      if (libraryItems.length !== libraryItemIds.length) {
213	        return res.status(400).send('Invalid playlist items. Items not found')
214	      }
215	      /** @type {import('../models/PlaylistMediaItem')[]} */
216	      const existingPlaylistMediaItems = await req.playlist.getPlaylistMediaItems({
217	        order: [['order', 'ASC']]
218	      })
219	      if (existingPlaylistMediaItems.length !== reqBody.items.length) {
220	        return res.status(400).send('Invalid playlist items. Length mismatch')
221	      }
222	
223	      // Set an array of mediaItemId
224	      const newMediaItemIdOrder = []
225	      for (const item of reqBody.items) {
226	        const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
227	        const mediaItemId = item.episodeId || libraryItem.mediaId
228	        newMediaItemIdOrder.push(mediaItemId)
229	      }
230	
231	      // Sort existing playlist media items into new order
232	      existingPlaylistMediaItems.sort((a, b) => {
233	        const aIndex = newMediaItemIdOrder.findIndex((i) => i === a.mediaItemId)
234	        const bIndex = newMediaItemIdOrder.findIndex((i) => i === b.mediaItemId)
235	        return aIndex - bIndex
236	      })
237	
238	      // Update order on playlistMediaItem records
239	      for (const [index, playlistMediaItem] of existingPlaylistMediaItems.entries()) {
240	        if (playlistMediaItem.order !== index + 1) {
241	          await playlistMediaItem.update({
242	            order: index + 1
243	          })
244	          wasUpdated = true
245	        }
246	      }
247	    }
248	
249	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
250	
251	    const jsonExpanded = req.playlist.toOldJSONExpanded()
252	    if (wasUpdated) {
253	      SocketAuthority.clientEmitter(req.playlist.userId, 'playlist_updated', jsonExpanded)
254	    }
255	    res.json(jsonExpanded)
256	  }
257	
258	  /**
259	   * DELETE: /api/playlists/:id
260	   * Remove playlist
261	   *
262	   * @param {PlaylistControllerRequest} req
263	   * @param {Response} res
264	   */
265	  async delete(req, res) {
266	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
267	    const jsonExpanded = req.playlist.toOldJSONExpanded()
268	
269	    await req.playlist.destroy()
270	    SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_removed', jsonExpanded)
271	    res.sendStatus(200)
272	  }
273	
274	  /**
275	   * POST: /api/playlists/:id/item
276	   * Add item to playlist
277	   *
278	   * This is not used by Abs web client or mobile apps. Only the batch endpoints are used.
279	   *
280	   * @param {PlaylistControllerRequest} req
281	   * @param {Response} res
282	   */
283	  async addItem(req, res) {
284	    const itemToAdd = req.body || {}
285	
286	    if (!itemToAdd.libraryItemId) {
287	      return res.status(400).send('Request body has no libraryItemId')
288	    }
289	
290	    const libraryItem = await Database.libraryItemModel.getExpandedById(itemToAdd.libraryItemId)
291	    if (!libraryItem) {
292	      return res.status(400).send('Library item not found')
293	    }
294	    if (libraryItem.libraryId !== req.playlist.libraryId) {
295	      return res.status(400).send('Library item in different library')
296	    }
297	    if ((itemToAdd.episodeId && !libraryItem.isPodcast) || (libraryItem.isPodcast && !itemToAdd.episodeId)) {
298	      return res.status(400).send('Invalid item to add for this library type')
299	    }
300	    if (itemToAdd.episodeId && !libraryItem.media.podcastEpisodes.some((pe) => pe.id === itemToAdd.episodeId)) {
301	      return res.status(400).send('Episode not found in library item')
302	    }
303	
304	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
305	
306	    if (req.playlist.checkHasMediaItem(itemToAdd.libraryItemId, itemToAdd.episodeId)) {
307	      return res.status(400).send('Item already in playlist')
308	    }
309	
310	    const jsonExpanded = req.playlist.toOldJSONExpanded()
311	
312	    const playlistMediaItem = {
313	      playlistId: req.playlist.id,
314	      mediaItemId: itemToAdd.episodeId || libraryItem.media.id,
315	      mediaItemType: itemToAdd.episodeId ? 'podcastEpisode' : 'book',
316	      order: req.playlist.playlistMediaItems.length + 1
317	    }
318	    await Database.playlistMediaItemModel.create(playlistMediaItem)
319	
320	    // Add the new item to to the old json expanded to prevent having to fully reload the playlist media items
321	    if (itemToAdd.episodeId) {
322	      const episode = libraryItem.media.podcastEpisodes.find((ep) => ep.id === itemToAdd.episodeId)
323	      jsonExpanded.items.push({
324	        episodeId: itemToAdd.episodeId,
325	        episode: episode.toOldJSONExpanded(libraryItem.id),
326	        libraryItemId: libraryItem.id,
327	        libraryItem: libraryItem.toOldJSONMinified()
328	      })
329	    } else {
330	      jsonExpanded.items.push({
331	        libraryItemId: libraryItem.id,
332	        libraryItem: libraryItem.toOldJSONExpanded()
333	      })
334	    }
335	
336	    SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_updated', jsonExpanded)
337	    res.json(jsonExpanded)
338	  }
339	
340	  /**
341	   * DELETE: /api/playlists/:id/item/:libraryItemId/:episodeId?
342	   * Remove item from playlist
343	   *
344	   * @param {PlaylistControllerRequest} req
345	   * @param {Response} res
346	   */
347	  async removeItem(req, res) {
348	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
349	
350	    let playlistMediaItem = null
351	    if (req.params.episodeId) {
352	      playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItemId === req.params.episodeId)
353	    } else {
354	      playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItem.libraryItem?.id === req.params.libraryItemId)
355	    }
356	    if (!playlistMediaItem) {
357	      return res.status(404).send('Media item not found in playlist')
358	    }
359	
360	    // Remove record
361	    await playlistMediaItem.destroy()
362	    req.playlist.playlistMediaItems = req.playlist.playlistMediaItems.filter((pmi) => pmi.id !== playlistMediaItem.id)
363	
364	    // Update playlist media items order
365	    for (const [index, mediaItem] of req.playlist.playlistMediaItems.entries()) {
366	      if (mediaItem.order !== index + 1) {
367	        await mediaItem.update({
368	          order: index + 1
369	        })
370	      }
371	    }
372	
373	    const jsonExpanded = req.playlist.toOldJSONExpanded()
374	
375	    // Playlist is removed when there are no items
376	    if (!jsonExpanded.items.length) {
377	      Logger.info(`[PlaylistController] Playlist "${jsonExpanded.name}" has no more items - removing it`)
378	      await req.playlist.destroy()
379	      SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_removed', jsonExpanded)
380	    } else {
381	      SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_updated', jsonExpanded)
382	    }
383	
384	    res.json(jsonExpanded)
385	  }
386	
387	  /**
388	   * POST: /api/playlists/:id/batch/add
389	   * Batch add playlist items
390	   *
391	   * @param {PlaylistControllerRequest} req
392	   * @param {Response} res
393	   */
394	  async addBatch(req, res) {
395	    if (!req.body.items?.length || !Array.isArray(req.body.items) || req.body.items.some((i) => !i?.libraryItemId || typeof i.libraryItemId !== 'string' || (i.episodeId && typeof i.episodeId !== 'string'))) {
396	      return res.status(400).send('Invalid request body items')
397	    }
398	
399	    // Find all library items
400	    const libraryItemIds = new Set(req.body.items.map((i) => i.libraryItemId).filter((i) => i))
401	
402	    const libraryItems = await Database.libraryItemModel.findAllExpandedWhere({ id: Array.from(libraryItemIds) })
403	    if (libraryItems.length !== libraryItemIds.size) {
404	      return res.status(400).send('Invalid request body items')
405	    }
406	
407	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
408	
409	    const mediaItemsToAdd = []
410	    const jsonExpanded = req.playlist.toOldJSONExpanded()
411	
412	    // Setup array of playlistMediaItem records to add
413	    let order = req.playlist.playlistMediaItems.length + 1
414	    for (const item of req.body.items) {
415	      const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
416	
417	      const mediaItemId = item.episodeId || libraryItem.media.id
418	      if (req.playlist.playlistMediaItems.some((pmi) => pmi.mediaItemId === mediaItemId)) {
419	        // Already exists in playlist
420	        continue
421	      } else {
422	        mediaItemsToAdd.push({
423	          playlistId: req.playlist.id,
424	          mediaItemId,
425	          mediaItemType: item.episodeId ? 'podcastEpisode' : 'book',
426	          order: order++
427	        })
428	
429	        // Add the new item to to the old json expanded to prevent having to fully reload the playlist media items
430	        if (item.episodeId) {
431	          const episode = libraryItem.media.podcastEpisodes.find((ep) => ep.id === item.episodeId)
432	          jsonExpanded.items.push({
433	            episodeId: item.episodeId,
434	            episode: episode.toOldJSONExpanded(libraryItem.id),
435	            libraryItemId: libraryItem.id,
436	            libraryItem: libraryItem.toOldJSONMinified()
437	          })
438	        } else {
439	          jsonExpanded.items.push({
440	            libraryItemId: libraryItem.id,
441	            libraryItem: libraryItem.toOldJSONExpanded()
442	          })
443	        }
444	      }
445	    }
446	
447	    if (mediaItemsToAdd.length) {
448	      await Database.playlistMediaItemModel.bulkCreate(mediaItemsToAdd)
449	
450	      SocketAuthority.clientEmitter(req.playlist.userId, 'playlist_updated', jsonExpanded)
451	    }
452	
453	    res.json(jsonExpanded)
454	  }
455	
456	  /**
457	   * POST: /api/playlists/:id/batch/remove
458	   * Batch remove playlist items
459	   *
460	   * @param {PlaylistControllerRequest} req
461	   * @param {Response} res
462	   */
463	  async removeBatch(req, res) {
464	    if (!req.body.items?.length || !Array.isArray(req.body.items) || req.body.items.some((i) => !i?.libraryItemId || typeof i.libraryItemId !== 'string' || (i.episodeId && typeof i.episodeId !== 'string'))) {
465	      return res.status(400).send('Invalid request body items')
466	    }
467	
468	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
469	
470	    // Remove playlist media items
471	    let hasUpdated = false
472	    for (const item of req.body.items) {
473	      let playlistMediaItem = null
474	      if (item.episodeId) {
475	        playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItemId === item.episodeId)
476	      } else {
477	        playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItem.libraryItem?.id === item.libraryItemId)
478	      }
479	      if (!playlistMediaItem) {
480	        Logger.warn(`[PlaylistController] Playlist item not found in playlist ${req.playlist.id}`, item)
481	        continue
482	      }
483	
484	      await playlistMediaItem.destroy()
485	      req.playlist.playlistMediaItems = req.playlist.playlistMediaItems.filter((pmi) => pmi.id !== playlistMediaItem.id)
486	
487	      hasUpdated = true
488	    }
489	
490	    const jsonExpanded = req.playlist.toOldJSONExpanded()
491	    if (hasUpdated) {
492	      // Playlist is removed when there are no items
493	      if (!req.playlist.playlistMediaItems.length) {
494	        Logger.info(`[PlaylistController] Playlist "${req.playlist.name}" has no more items - removing it`)
495	        await req.playlist.destroy()
496	        SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_removed', jsonExpanded)
497	      } else {
498	        SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_updated', jsonExpanded)
499	      }
500	    }
501	    res.json(jsonExpanded)
502	  }
503	
504	  /**
505	   * POST: /api/playlists/collection/:collectionId
506	   * Create a playlist from a collection
507	   *
508	   * @param {RequestWithUser} req
509	   * @param {Response} res
510	   */
511	  async createFromCollection(req, res) {
512	    const collection = await Database.collectionModel.findByPk(req.params.collectionId)
513	    if (!collection) {
514	      return res.status(404).send('Collection not found')
515	    }
516	    if (!req.user.checkCanAccessLibrary(collection.libraryId)) {
517	      Logger.warn(`[PlaylistController] User "${req.user.username}" attempted to create playlist from collection ${collection.id} in inaccessible library ${collection.libraryId}`)
518	      return res.status(404).send('Collection not found')
519	    }
520	    // Expand collection to get library items
521	    const collectionExpanded = await collection.getOldJsonExpanded(req.user)
522	    if (!collectionExpanded) {
523	      // This can happen if the user has no access to all items in collection
524	      return res.status(404).send('Collection not found')
525	    }
526	
527	    // Playlists cannot be empty
528	    if (!collectionExpanded.books.length) {
529	      return res.status(400).send('Collection has no books')
530	    }
531	
532	    const transaction = await Database.sequelize.transaction()
533	    try {
534	      const playlist = await Database.playlistModel.create(
535	        {
536	          userId: req.user.id,
537	          libraryId: collection.libraryId,
538	          name: collection.name,
539	          description: collection.description || null
540	        },
541	        { transaction }
542	      )
543	
544	      const mediaItemsToAdd = []
545	      for (const [index, libraryItem] of collectionExpanded.books.entries()) {
546	        mediaItemsToAdd.push({
547	          playlistId: playlist.id,
548	          mediaItemId: libraryItem.media.id,
549	          mediaItemType: 'book',
550	          order: index + 1
551	        })
552	      }
553	      await Database.playlistMediaItemModel.bulkCreate(mediaItemsToAdd, { transaction })
554	
555	      await transaction.commit()
556	
557	      playlist.playlistMediaItems = await playlist.getMediaItemsExpandedWithLibraryItem()
558	
559	      const jsonExpanded = playlist.toOldJSONExpanded()
560	      SocketAuthority.clientEmitter(playlist.userId, 'playlist_added', jsonExpanded)
561	      res.json(jsonExpanded)
562	    } catch (error) {
563	      await transaction.rollback()
564	      Logger.error('[PlaylistController] createFromCollection:', error)
565	      res.status(500).send('Failed to create playlist')
566	    }
567	  }
568	
569	  /**
570	   *
571	   * @param {RequestWithUser} req
572	   * @param {Response} res
573	   * @param {NextFunction} next
574	   */
575	  async middleware(req, res, next) {
576	    if (req.params.id) {
577	      const playlist = await Database.playlistModel.findByPk(req.params.id)
578	      if (!playlist) {
579	        return res.status(404).send('Playlist not found')
580	      }
581	      if (playlist.userId !== req.user.id) {
582	        Logger.warn(`[PlaylistController] Playlist ${req.params.id} requested by user ${req.user.id} that is not the owner`)
583	        return res.sendStatus(403)
