247	  /**
248	   * PATCH: /api/libraries/:id
249	   *
250	   * @this {import('../routers/ApiRouter')}
251	   *
252	   * @param {LibraryControllerRequest} req
253	   * @param {Response} res
254	   */
255	  async update(req, res) {
256	    if (!req.user.isAdminOrUp) {
257	      Logger.error(`[LibraryController] Non-admin user "${req.user.username}" attempted to update library`)
258	      return res.sendStatus(403)
259	    }
260	
261	    // Validation
262	    const updatePayload = {}
263	    const keysToCheck = ['name', 'provider', 'mediaType', 'icon']
264	    for (const key of keysToCheck) {
265	      if (!req.body[key]) continue
266	      if (typeof req.body[key] !== 'string') {
267	        Logger.error(`[LibraryController] Invalid request. ${key} must be a string`)
268	        return res.status(400).send(`Invalid request. ${key} must be a string`)
269	      }
270	      updatePayload[key] = req.body[key]
271	    }
272	    if (req.body.displayOrder !== undefined) {
273	      if (isNaN(req.body.displayOrder)) {
274	        Logger.error(`[LibraryController] Invalid request. displayOrder must be a number`)
275	        return res.status(400).send('Invalid request. displayOrder must be a number')
276	      }
277	      updatePayload.displayOrder = req.body.displayOrder
278	    }
279	
280	    // Validate that the custom provider exists if given any
281	    if (req.body.provider?.startsWith('custom-')) {
282	      if (!(await Database.customMetadataProviderModel.checkExistsBySlug(req.body.provider))) {
283	        Logger.error(`[LibraryController] Custom metadata provider "${req.body.provider}" does not exist`)
284	        return res.status(400).send('Custom metadata provider does not exist')
285	      }
286	    }
287	
288	    // Validate settings
289	    const defaultLibrarySettings = Database.libraryModel.getDefaultLibrarySettingsForMediaType(req.library.mediaType)
290	    const updatedSettings = {
291	      ...(req.library.settings || defaultLibrarySettings)
292	    }
293	    // In case new settings are added in the future, ensure all settings are present
294	    for (const key in defaultLibrarySettings) {
295	      if (updatedSettings[key] === undefined) {
296	        updatedSettings[key] = defaultLibrarySettings[key]
297	      }
298	    }
299	
300	    let hasUpdates = false
301	    let hasUpdatedDisableWatcher = false
302	    let hasUpdatedScanCron = false
303	    if (req.body.settings) {
304	      for (const key in req.body.settings) {
305	        if (!Object.keys(defaultLibrarySettings).includes(key)) {
306	          continue
307	        }
308	
309	        if (key === 'metadataPrecedence') {
310	          if (!Array.isArray(req.body.settings[key])) {
311	            Logger.error(`[LibraryController] Invalid request. Settings "metadataPrecedence" must be an array`)
312	            return res.status(400).send('Invalid request. Settings "metadataPrecedence" must be an array')
313	          }
314	          if (JSON.stringify(req.body.settings[key]) !== JSON.stringify(updatedSettings[key])) {
315	            hasUpdates = true
316	            updatedSettings[key] = [...req.body.settings[key]]
317	            Logger.debug(`[LibraryController] Library "${req.library.name}" updating setting "${key}" to "${updatedSettings[key]}"`)
318	          }
319	        } else if (key === 'autoScanCronExpression' || key === 'podcastSearchRegion') {
320	          if (req.body.settings[key] !== null && typeof req.body.settings[key] !== 'string') {
321	            Logger.error(`[LibraryController] Invalid request. Settings "${key}" must be a string`)
322	            return res.status(400).send(`Invalid request. Settings "${key}" must be a string`)
323	          }
324	          if (req.body.settings[key] !== updatedSettings[key]) {
325	            if (key === 'autoScanCronExpression') hasUpdatedScanCron = true
326	
327	            hasUpdates = true
328	            updatedSettings[key] = req.body.settings[key]
329	            Logger.debug(`[LibraryController] Library "${req.library.name}" updating setting "${key}" to "${updatedSettings[key]}"`)
330	          }
331	        } else if (key === 'markAsFinishedPercentComplete') {
332	          if (req.body.settings[key] !== null && isNaN(req.body.settings[key])) {
333	            Logger.error(`[LibraryController] Invalid request. Setting "${key}" must be a number`)
334	            return res.status(400).send(`Invalid request. Setting "${key}" must be a number`)
335	          } else if (req.body.settings[key] !== null && (Number(req.body.settings[key]) < 0 || Number(req.body.settings[key]) > 100)) {
336	            Logger.error(`[LibraryController] Invalid request. Setting "${key}" must be between 0 and 100`)
337	            return res.status(400).send(`Invalid request. Setting "${key}" must be between 0 and 100`)
338	          }
339	          if (req.body.settings[key] !== updatedSettings[key]) {
340	            hasUpdates = true
341	            updatedSettings[key] = req.body.settings[key] === null ? null : Number(req.body.settings[key])
342	            Logger.debug(`[LibraryController] Library "${req.library.name}" updating setting "${key}" to "${updatedSettings[key]}"`)
343	          }
344	        } else if (key === 'markAsFinishedTimeRemaining') {
345	          if (req.body.settings[key] !== null && isNaN(req.body.settings[key])) {
346	            Logger.error(`[LibraryController] Invalid request. Setting "${key}" must be a number`)
347	            return res.status(400).send(`Invalid request. Setting "${key}" must be a number`)
348	          } else if (req.body.settings[key] !== null && Number(req.body.settings[key]) < 0) {
349	            Logger.error(`[LibraryController] Invalid request. Setting "${key}" must be greater than or equal to 0`)
350	            return res.status(400).send(`Invalid request. Setting "${key}" must be greater than or equal to 0`)
351	          }
352	          if (req.body.settings[key] !== updatedSettings[key]) {
353	            hasUpdates = true
354	            updatedSettings[key] = req.body.settings[key] === null ? null : Number(req.body.settings[key])
355	            Logger.debug(`[LibraryController] Library "${req.library.name}" updating setting "${key}" to "${updatedSettings[key]}"`)
356	          }
357	        } else {
358	          if (typeof req.body.settings[key] !== typeof updatedSettings[key]) {
359	            Logger.error(`[LibraryController] Invalid request. Setting "${key}" must be of type ${typeof updatedSettings[key]}`)
360	            return res.status(400).send(`Invalid request. Setting "${key}" must be of type ${typeof updatedSettings[key]}`)
361	          }
362	          if (req.body.settings[key] !== updatedSettings[key]) {
363	            if (key === 'disableWatcher') hasUpdatedDisableWatcher = true
364	
365	            hasUpdates = true
366	            updatedSettings[key] = req.body.settings[key]
367	            Logger.debug(`[LibraryController] Library "${req.library.name}" updating setting "${key}" to "${updatedSettings[key]}"`)
368	          }
369	        }
370	      }
371	      if (hasUpdates) {
372	        updatePayload.settings = updatedSettings
373	        req.library.changed('settings', true)
374	      }
375	    }
376	
377	    let hasFolderUpdates = false
378	    // Validate new folder paths exist or can be created & resolve rel paths
379	    //   returns 400 if a new folder fails to access
380	    if (Array.isArray(req.body.folders)) {
381	      const newFolderPaths = []
382	      req.body.folders = req.body.folders.map((f) => {
383	        if (!f.id) {
384	          const path = f.fullPath || f.path
385	          f.path = fileUtils.filePathToPOSIX(Path.resolve(path))
386	          newFolderPaths.push(f.path)
387	        }
388	        return f
389	      })
390	      for (const path of newFolderPaths) {
391	        const pathExists = await fs.pathExists(path)
392	        if (!pathExists) {
393	          const success = await fs
394	            .ensureDir(path)
395	            .then(() => true)
396	            .catch((error) => {
397	              Logger.error(`[LibraryController] Failed to ensure folder dir "${path}"`, error)
398	              return false
399	            })
400	          if (!success) {
401	            Logger.error(`[LibraryController] Invalid folder directory "${path}"`)
402	            return res.status(400).send(`Invalid folder directory "${path}"`)
403	          }
404	        }
405	        // Create folder
406	        const libraryFolder = await Database.libraryFolderModel.create({
407	          path,
408	          libraryId: req.library.id
409	        })
410	        Logger.info(`[LibraryController] Created folder "${libraryFolder.path}" for library "${req.library.name}"`)
411	        hasFolderUpdates = true
412	      }
413	
414	      // Handle removing folders
415	      for (const folder of req.library.libraryFolders) {
416	        if (!req.body.folders.some((f) => f.id === folder.id)) {
417	          // Remove library items in folder
418	          const libraryItemsInFolder = await Database.libraryItemModel.findAll({
419	            where: {
420	              libraryFolderId: folder.id
421	            },
422	            attributes: ['id', 'mediaId', 'mediaType'],
423	            include: [
424	              {
425	                model: Database.podcastModel,
426	                attributes: ['id'],
427	                include: {
428	                  model: Database.podcastEpisodeModel,
429	                  attributes: ['id']
430	                }
431	              },
432	              {
433	                model: Database.bookModel,
434	                attributes: ['id'],
435	                include: [
436	                  {
437	                    model: Database.bookAuthorModel,
438	                    attributes: ['authorId']
439	                  },
440	                  {
441	                    model: Database.bookSeriesModel,
442	                    attributes: ['seriesId']
443	                  }
444	                ]
445	              }
446	            ]
447	          })
448	          Logger.info(`[LibraryController] Removed folder "${folder.path}" from library "${req.library.name}" with ${libraryItemsInFolder.length} library items`)
449	          const seriesIds = []
450	          const authorIds = []
451	          for (const libraryItem of libraryItemsInFolder) {
452	            let mediaItemIds = []
453	            if (req.library.isPodcast) {
454	              mediaItemIds = libraryItem.media.podcastEpisodes.map((pe) => pe.id)
455	            } else {
456	              mediaItemIds.push(libraryItem.mediaId)
457	              if (libraryItem.media.bookAuthors.length) {
458	                authorIds.push(...libraryItem.media.bookAuthors.map((ba) => ba.authorId))
459	              }
460	              if (libraryItem.media.bookSeries.length) {
461	                seriesIds.push(...libraryItem.media.bookSeries.map((bs) => bs.seriesId))
462	              }
463	            }
464	            Logger.info(`[LibraryController] Removing library item "${libraryItem.id}" from folder "${folder.path}"`)
465	            await this.handleDeleteLibraryItem(libraryItem.id, mediaItemIds, req.library.id)
466	          }
467	
468	          if (authorIds.length) {
469	            await this.checkRemoveAuthorsWithNoBooks(authorIds)
470	          }
471	          if (seriesIds.length) {
472	            await this.checkRemoveEmptySeries(seriesIds)
473	          }
474	
475	          // Remove folder
476	          await folder.destroy()
477	          hasFolderUpdates = true
478	        }
479	      }
480	    }
481	
482	    if (Object.keys(updatePayload).length) {
483	      req.library.set(updatePayload)
484	      if (req.library.changed()) {
485	        Logger.debug(`[LibraryController] Updated library "${req.library.name}" with changed keys ${req.library.changed()}`)
486	        hasUpdates = true
487	        await req.library.save()
488	      }
489	    }
490	
491	    if (hasUpdatedScanCron) {
492	      Logger.debug(`[LibraryController] Updated library "${req.library.name}" auto scan cron`)
493	      // Update auto scan cron
494	      this.cronManager.updateLibraryScanCron(req.library)
495	    }
496	
497	    if (hasFolderUpdates || hasUpdatedDisableWatcher) {
498	      req.library.libraryFolders = await req.library.getLibraryFolders()
499	
500	      // Update watcher
501	      Watcher.updateLibrary(req.library)
502	
503	      hasUpdates = true
504	    }
505	
506	    if (hasUpdates) {
507	      // Only emit to users with access to library
508	      const userFilter = (user) => {
509	        return user.checkCanAccessLibrary?.(req.library.id)
510	      }
511	      SocketAuthority.emitter('library_updated', req.library.toOldJSON(), userFilter)
512	
513	      await Database.resetLibraryIssuesFilterData(req.library.id)
514	    }
515	    return res.json(req.library.toOldJSON())
516	  }
