1021	  async getAuthors(req, res) {
1022	    const isPaginated = req.query.limit && !isNaN(req.query.limit) && !isNaN(req.query.page)
1023	
1024	    const payload = {
1025	      results: [],
1026	      total: 0,
1027	      limit: isPaginated ? Number(req.query.limit) : 0,
1028	      page: isPaginated ? Number(req.query.page) : 0,
1029	      sortBy: req.query.sort,
1030	      sortDesc: req.query.desc === '1',
1031	      filterBy: req.query.filter,
1032	      minified: req.query.minified === '1',
1033	      include: req.query.include
1034	    }
1035	
1036	    // create order, limit and offset for pagination
1037	    let offset = isPaginated ? payload.page * payload.limit : undefined
1038	    let limit = isPaginated ? payload.limit : undefined
1039	    let order = undefined
1040	    const direction = payload.sortDesc ? 'DESC' : 'ASC'
1041	    if (payload.sortBy === 'name') {
1042	      order = [[Sequelize.literal('name COLLATE NOCASE'), direction]]
1043	    } else if (payload.sortBy === 'lastFirst') {
1044	      order = [[Sequelize.literal('lastFirst COLLATE NOCASE'), direction]]
1045	    } else if (payload.sortBy === 'addedAt') {
1046	      order = [['createdAt', direction]]
1047	    } else if (payload.sortBy === 'updatedAt') {
1048	      order = [['updatedAt', direction]]
1049	    } else if (payload.sortBy === 'numBooks') {
1050	      offset = undefined
1051	      limit = undefined
1052	    }
1053	
1054	    const { bookWhere, replacements } = libraryItemsBookFilters.getUserPermissionBookWhereQuery(req.user)
1055	    const { rows: authors, count } = await Database.authorModel.findAndCountAll({
1056	      where: {
1057	        libraryId: req.library.id
1058	      },
1059	      replacements,
1060	      include: {
