1062	        attributes: ['id', 'tags', 'explicit'],
1063	        where: bookWhere,
1064	        required: !req.user.isAdminOrUp, // Only show authors with 0 books for admin users or up
1065	        through: {
1066	          attributes: []
1067	        }
1068	      },
1069	      order: order,
1070	      limit: limit,
1071	      offset: offset,
1072	      distinct: true
1073	    })
1074	
1075	    let oldAuthors = []
1076	
1077	    for (const author of authors) {
