1079	      oldAuthor.lastFirst = author.lastFirst
1080	      oldAuthors.push(oldAuthor)
1081	    }
1082	
1083	    // numBooks sort is handled post-query
1084	    if (payload.sortBy === 'numBooks') {
1085	      oldAuthors.sort((a, b) => (payload.sortDesc ? b.numBooks - a.numBooks : a.numBooks - b.numBooks))
1086	      if (isPaginated) {
1087	        const startIndex = payload.page * payload.limit
1088	        const endIndex = startIndex + payload.limit
1089	        oldAuthors = oldAuthors.slice(startIndex, endIndex)
1090	      }
1091	    }
1092	
1093	    payload.results = oldAuthors
1094	    if (isPaginated) {
1095	      payload.total = count
1096	      res.json(payload)
1097	    } else {
1098	      res.json({
1099	        authors: payload.results
1100	      })
1101	    }
